package com.chronos.integration.model; import com.chronos.model.pojo.BaseEntity; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="int_connector") @Getter @Setter public class Connector extends BaseEntity { @Column(nullable=false,length=120) private String name; @Column(nullable=false,length=30) private String type="HTTP"; @Column(name="base_url",nullable=false,length=1000) private String baseUrl; @Column(length=20) private String status="ACTIVE"; @Column(name="timeout_ms") private Integer timeoutMs=10000; @Column(name="max_retries") private Integer maxRetries=3; @Column(name="config_json",columnDefinition="text") private String configJson="{}"; }
